export const vendorDict: Readonly<Record<Lang, VendorDict>> = { ru, uz };

/** Название языка на нём самом — для подсказки в переключателе */
export const LANG_NAMES: Readonly<Record<Lang, string>> = { ru: "Русский", uz: "Oʻzbekcha" };

/** Подстановка {имя} → значение. Неизвестное имя остаётся как есть — это видно в тесте */
export function fill(template: string, values: Readonly<Record<string, string | number>>): string {
  return template.replace(/\{(\w+)\}/g, (match, name: string) =>
    name in values ? String(values[name]) : match,
  );
}

/** Текст по ключу, собранному из кода (st_ + статус): неизвестный код — сам код, а не undefined */
export function textOf(t: VendorDict, key: string): string {
  const value = (t as Readonly<Record<string, unknown>>)[key];
  return typeof value === "string" ? value : key;
}
